"use client";

import { FormEvent, useState } from "react";
import { useRouter } from "next/navigation";

async function post(url: string, body: object) { const response = await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const payload = await response.json().catch(() => ({})) as { error?: string }; if (!response.ok) throw new Error(payload.error ?? "Request failed"); }

export function AdminAchievementForm() { const router = useRouter(); const [message, setMessage] = useState<string | null>(null); async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const body = { code: String(form.get("code") ?? "").toUpperCase(), title: String(form.get("title") ?? ""), description: String(form.get("description") ?? ""), icon: String(form.get("icon") ?? "🏅"), category: String(form.get("category") ?? "LEARNING"), rarity: String(form.get("rarity") ?? "COMMON"), conditionType: String(form.get("conditionType") ?? "LESSONS_COMPLETED"), target: Number(form.get("target") ?? 1), experienceReward: Number(form.get("experienceReward") ?? 0), coinReward: Number(form.get("coinReward") ?? 0), isTrophy: form.get("isTrophy") === "on", isHidden: form.get("isHidden") === "on", isActive: true, order: Number(form.get("order") ?? 0) }; try { await post("/api/admin/achievements", body); setMessage("Achievement created."); event.currentTarget.reset(); router.refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : "Unable to create achievement"); } } return <form onSubmit={(event) => void submit(event)} className="mt-7 grid gap-3 rounded-2xl border bg-white p-5 md:grid-cols-3"><h2 className="text-xl font-bold md:col-span-3">Create achievement</h2><label className="text-sm">Code<input required name="code" placeholder="FIRST_LESSON" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">Title<input required name="title" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">Icon<input required name="icon" defaultValue="🏅" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm md:col-span-3">Description<input required name="description" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">Category<select name="category" className="mt-1 w-full rounded border px-3 py-2">{["LEARNING", "LESSONS", "COURSES", "VOCABULARY", "STREAK", "ACCURACY", "TIME", "EXPERIENCE", "SPECIAL"].map((value) => <option key={value}>{value}</option>)}</select></label><label className="text-sm">Rarity<select name="rarity" className="mt-1 w-full rounded border px-3 py-2">{["COMMON", "RARE", "EPIC", "LEGENDARY"].map((value) => <option key={value}>{value}</option>)}</select></label><label className="text-sm">Condition<select name="conditionType" className="mt-1 w-full rounded border px-3 py-2">{["LESSONS_COMPLETED", "COURSES_COMPLETED", "EXERCISES_CORRECT", "VOCABULARY_REVIEWS", "STREAK_DAYS", "ACTIVE_MINUTES", "EXPERIENCE_EARNED", "PERFECT_LESSONS"].map((value) => <option key={value}>{value}</option>)}</select></label><label className="text-sm">Target<input required name="target" type="number" min="1" defaultValue="1" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">XP reward<input name="experienceReward" type="number" min="0" defaultValue="0" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">Coin reward<input name="coinReward" type="number" min="0" defaultValue="0" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">Order<input name="order" type="number" min="0" defaultValue="0" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="flex items-center gap-2 text-sm"><input name="isTrophy" type="checkbox" /> Trophy</label><label className="flex items-center gap-2 text-sm"><input name="isHidden" type="checkbox" /> Hidden until earned</label><div className="md:col-span-3"><button className="rounded bg-blue-700 px-4 py-2 font-semibold text-white">Create achievement</button>{message ? <p role="status" className="mt-3 text-sm">{message}</p> : null}</div></form>; }

export function AdminRewardAdjustmentForm() { const [message, setMessage] = useState<string | null>(null); async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); try { await post("/api/admin/rewards/adjustments", { userId: String(form.get("userId") ?? ""), experienceAmount: Number(form.get("experienceAmount") ?? 0), coinAmount: Number(form.get("coinAmount") ?? 0), reason: String(form.get("reason") ?? "") }); setMessage("Adjustment recorded in immutable reward transactions."); event.currentTarget.reset(); } catch (error) { setMessage(error instanceof Error ? error.message : "Unable to adjust rewards"); } } return <form onSubmit={(event) => void submit(event)} className="mt-8 grid gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-5 md:grid-cols-2"><h2 className="text-xl font-bold md:col-span-2">Administrative adjustment</h2><label className="text-sm">User ID<input required name="userId" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">Reason<input required name="reason" minLength={3} className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">XP (+/-)<input name="experienceAmount" type="number" defaultValue="0" className="mt-1 w-full rounded border px-3 py-2" /></label><label className="text-sm">Coins (+/-)<input name="coinAmount" type="number" defaultValue="0" className="mt-1 w-full rounded border px-3 py-2" /></label><div className="md:col-span-2"><button className="rounded bg-slate-900 px-4 py-2 font-semibold text-white">Record adjustment</button>{message ? <p role="status" className="mt-3 text-sm">{message}</p> : null}</div></form>; }
